/* 
  ❌ BAD: Deeply nested arrays (Slow to search, hard to update)
*/
const badState = [
  {
    id: 'user1',
    name: 'John',
    posts: [
      { id: 'post1', text: 'Hello' }
    ]
  }
];

/* 
  ✅ GOOD: Normalized state (Instant lookup! O(1) time complexity)
*/
const goodState = {
  users: {
    byId: {
      'user1': { id: 'user1', name: 'John', postIds: ['post1'] }
    },
    allIds: ['user1']
  },
  posts: {
    byId: {
      'post1': { id: 'post1', author: 'user1', text: 'Hello' }
    },
    allIds: ['post1']
  }
};
